inline void rounded(HDC dc,RECT r,COLORREF color,COLORREF edge=CLR_INVALID,int radius=8){
    if(r.right<=r.left||r.bottom<=r.top)return;
    Gdiplus::Graphics g(dc);g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);Gdiplus::GraphicsPath p;float x=float(r.left)+.5f,y=float(r.top)+.5f,w=float(r.right-r.left)-1,h=float(r.bottom-r.top)-1,d=float(pf::min(radius*2,pf::min(w,h)));
    p.AddArc(x,y,d,d,180,90);p.AddArc(x+w-d,y,d,d,270,90);p.AddArc(x+w-d,y+h-d,d,d,0,90);p.AddArc(x,y+h-d,d,d,90,90);p.CloseFigure();
    auto c=[](COLORREF v){return Gdiplus::Color(255,GetRValue(v),GetGValue(v),GetBValue(v));};Gdiplus::SolidBrush b(c(color));g.FillPath(&b,&p);if(edge!=CLR_INVALID){Gdiplus::Pen pen(c(edge));g.DrawPath(&pen,&p);}
}
